/** Front-camera access and a per-frame landmark loop. */
import type { FrameObservation } from '../core';
import type { FaceEngine } from './landmarker';

export type CameraError = 'insecure' | 'unsupported' | 'permission' | 'notFound' | 'busy' | 'unknown';

export async function openCamera(video: HTMLVideoElement): Promise<MediaStream> {
  if (!window.isSecureContext) throw Object.assign(new Error('insecure'), { code: 'insecure' as CameraError });
  if (!navigator.mediaDevices?.getUserMedia) throw Object.assign(new Error('unsupported'), { code: 'unsupported' as CameraError });
  let stream: MediaStream;
  try {
    stream = await navigator.mediaDevices.getUserMedia({
      audio: false,
      video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 }, frameRate: { ideal: 30 } },
    });
  } catch (e) {
    const name = (e as DOMException).name;
    const code: CameraError =
      name === 'NotAllowedError' || name === 'SecurityError'
        ? 'permission'
        : name === 'NotFoundError' || name === 'OverconstrainedError'
          ? 'notFound'
          : name === 'NotReadableError'
            ? 'busy'
            : 'unknown';
    throw Object.assign(new Error(name), { code });
  }
  video.srcObject = stream;
  video.muted = true;
  video.playsInline = true;
  await video.play();
  return stream;
}

export function closeCamera(stream: MediaStream | null): void {
  stream?.getTracks().forEach((t) => t.stop());
}

export function cameraLabel(stream: MediaStream | null): string | null {
  const t = stream?.getVideoTracks()[0];
  if (!t) return null;
  const s = t.getSettings();
  return `${s.width ?? '?'}x${s.height ?? '?'}@${Math.round(s.frameRate ?? 0)}fps`;
}

/** Runs the landmarker on every new video frame until stopped. */
export function startFrameLoop(video: HTMLVideoElement, engine: FaceEngine, onFrame: (obs: FrameObservation) => void): () => void {
  let stopped = false;
  let busy = false;
  const hasRvfc = 'requestVideoFrameCallback' in HTMLVideoElement.prototype;
  const schedule = () => {
    if (stopped) return;
    if (hasRvfc) video.requestVideoFrameCallback(tick);
    else requestAnimationFrame(tick);
  };
  const tick = () => {
    if (stopped) return;
    if (busy || video.readyState < 2 || video.videoWidth === 0) return schedule();
    busy = true;
    engine
      .detectVideo(video)
      .then((obs) => {
        if (!stopped) onFrame(obs);
      })
      .catch(() => undefined)
      .finally(() => {
        busy = false;
        schedule();
      });
  };
  schedule();
  return () => {
    stopped = true;
  };
}
